/* Wishweave Wonders — renderer utilities (WW.render.util), docs/ARCHITECTURE.md §8.
   Offscreen canvases, cached sprites (tints, glows, shadows), atlas frame drawing, polygon/band geometry.
   Only defines functions at load; every cache is built lazily on first use and kept for the renderer's life. */
(function (WW) {
  'use strict';
  WW.render = WW.render || {};

  const clamp = function (v, lo, hi) { return v < lo ? lo : v > hi ? hi : v; };
  const lerp = function (a, b, t) { return a + (b - a) * t; };
  const smooth = function (t) { t = clamp(t, 0, 1); return t * t * (3 - 2 * t); };
  const easeOutCubic = function (t) { t = clamp(t, 0, 1); return 1 - Math.pow(1 - t, 3); };
  const easeInOut = function (t) { t = clamp(t, 0, 1); return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; };
  const easeOutBack = function (t) { t = clamp(t, 0, 1); const c = 1.70158; t -= 1; return 1 + (c + 1) * t * t * t + c * t * t; };

  function makeCanvas(w, h) {
    const c = (typeof document !== 'undefined') ? document.createElement('canvas') : null;
    if (!c) return null;
    c.width = Math.max(1, Math.ceil(w)); c.height = Math.max(1, Math.ceil(h));
    return c;
  }

  /* Supports ctx.filter (Chrome/Android WebView). Only used while building caches, never per frame. */
  let filterOK = null;
  function canFilter() {
    if (filterOK !== null) return filterOK;
    try { const c = makeCanvas(2, 2).getContext('2d'); c.filter = 'blur(2px)'; filterOK = c.filter === 'blur(2px)'; }
    catch (e) { filterOK = false; }
    return filterOK;
  }

  function imgReady(img) {
    return !!img && (img.complete === undefined || img.complete) && (img.naturalWidth || img.width) > 0;
  }

  /* Draws an atlas frame with its pivot at (x, y), uniformly scaled; sx/sy multiply the scale (squash). */
  function drawFrame(ctx, img, fr, x, y, scale, sx, sy, alpha) {
    if (!fr || !imgReady(img)) return false;
    sx = sx === undefined ? 1 : sx; sy = sy === undefined ? 1 : sy;
    const kx = scale * sx, ky = scale * sy;
    const prevA = ctx.globalAlpha;
    if (alpha !== undefined) ctx.globalAlpha = prevA * alpha;
    ctx.drawImage(img, fr.x, fr.y, fr.w, fr.h, x - fr.px * kx, y - fr.py * ky, fr.w * kx, fr.h * ky);
    ctx.globalAlpha = prevA;
    return true;
  }

  /* Cached canvas of a frame (optionally a sub-rectangle of it), with a tint applied once.
     mode 'multiply' keeps shading (used for the coral roll), 'silhouette' fills the alpha with a flat colour (rims). */
  function frameCanvas(cache, key, img, fr, build) {
    if (cache[key]) return cache[key];
    if (!imgReady(img)) return null;
    const c = makeCanvas(fr.w, fr.h), g = c.getContext('2d');
    g.drawImage(img, fr.x, fr.y, fr.w, fr.h, 0, 0, fr.w, fr.h);
    if (build) build(g, c);
    cache[key] = c;
    return c;
  }

  function silhouette(g, c, color) {
    g.globalCompositeOperation = 'source-in';
    g.fillStyle = color; g.fillRect(0, 0, c.width, c.height);
    g.globalCompositeOperation = 'source-over';
  }

  /* Soft radial glow sprite (64×64), drawn scaled. */
  function glowSprite(cache, color, inner) {
    const key = 'glow:' + color + ':' + (inner || 0);
    if (cache[key]) return cache[key];
    const c = makeCanvas(64, 64), g = c.getContext('2d');
    const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    gr.addColorStop(0, color);
    gr.addColorStop(inner || 0.25, color);
    gr.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
    cache[key] = c;
    return c;
  }

  /* Contact shadow: warm dark ellipse with a soft edge (128×48). */
  function shadowSprite(cache) {
    if (cache.shadow) return cache.shadow;
    const c = makeCanvas(128, 48), g = c.getContext('2d');
    g.translate(64, 24); g.scale(1, 24 / 64);
    const gr = g.createRadialGradient(0, 0, 0, 0, 0, 64);
    gr.addColorStop(0, 'rgba(48,18,10,0.85)');
    gr.addColorStop(0.45, 'rgba(48,18,10,0.55)');
    gr.addColorStop(1, 'rgba(48,18,10,0)');
    g.fillStyle = gr; g.beginPath(); g.arc(0, 0, 64, 0, Math.PI * 2); g.fill();
    cache.shadow = c;
    return c;
  }

  function drawShadow(ctx, cache, x, y, w, alpha) {
    const s = shadowSprite(cache);
    const prev = ctx.globalAlpha;
    ctx.globalAlpha = prev * alpha;
    ctx.drawImage(s, x - w / 2, y - w * 0.19, w, w * 0.375);
    ctx.globalAlpha = prev;
  }

  /* Four-point sparkle star. */
  function star(ctx, x, y, r, rot) {
    ctx.beginPath();
    for (let i = 0; i < 8; i++) {
      const a = rot + i * Math.PI / 4, rr = i % 2 ? r * 0.22 : r;
      const px = x + Math.cos(a) * rr, py = y + Math.sin(a) * rr;
      if (i) ctx.lineTo(px, py); else ctx.moveTo(px, py);
    }
    ctx.closePath();
    ctx.fill();
  }

  function polyPath(ctx, poly) {
    ctx.beginPath();
    for (let i = 0; i < poly.length; i++) {
      if (i) ctx.lineTo(poly[i][0], poly[i][1]); else ctx.moveTo(poly[i][0], poly[i][1]);
    }
    ctx.closePath();
  }

  function polyBox(poly) {
    let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
    for (let i = 0; i < poly.length; i++) {
      const p = poly[i];
      if (p[0] < x0) x0 = p[0]; if (p[0] > x1) x1 = p[0];
      if (p[1] < y0) y0 = p[1]; if (p[1] > y1) y1 = p[1];
    }
    return { x0: x0, y0: y0, x1: x1, y1: y1 };
  }

  function boxHit(a, b) { return a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0; }

  /* ---- Bands (ribbon / shortcut): centre line [x, y, halfWidth] with half-widths along the normal ---- */
  const SUB = 10;
  function cr(p0, p1, p2, p3, t) {
    const t2 = t * t, t3 = t2 * t;
    return 0.5 * ((2 * p1) + (-p0 + p2) * t + (2 * p0 - 5 * p1 + 4 * p2 - p3) * t2 + (-p0 + 3 * p1 - 3 * p2 + p3) * t3);
  }

  function buildBand(points) {
    const n = points.length, pts = [];
    const at = function (i) { return points[clamp(i, 0, n - 1)]; };
    for (let i = 0; i < n - 1; i++) {
      const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
      for (let k = 0; k < SUB; k++) {
        const t = k / SUB;
        pts.push({ x: cr(p0[0], p1[0], p2[0], p3[0], t), y: cr(p0[1], p1[1], p2[1], p3[1], t), hw: lerp(p1[2], p2[2], t) });
      }
    }
    const last = points[n - 1];
    pts.push({ x: last[0], y: last[1], hw: last[2] });
    const N = pts.length;
    let cum = 0;
    for (let i = 0; i < N; i++) {
      const a = pts[Math.max(0, i - 1)], b = pts[Math.min(N - 1, i + 1)];
      let tx = b.x - a.x, ty = b.y - a.y; const l = Math.hypot(tx, ty) || 1;
      tx /= l; ty /= l;
      pts[i].tx = tx; pts[i].ty = ty; pts[i].nx = -ty; pts[i].ny = tx;
      if (i) {
        const p = pts[i - 1], q = pts[i];
        cum += Math.hypot(q.x - p.x, q.y - p.y) / Math.max(8, (p.hw + q.hw) / 2);
      }
      pts[i].s = cum;
    }
    for (let i = 0; i < N; i++) pts[i].s /= (cum || 1);
    let box = { x0: Infinity, y0: Infinity, x1: -Infinity, y1: -Infinity };
    for (let i = 0; i < N; i++) {
      const p = pts[i];
      for (let side = -1; side <= 1; side += 2) {
        const x = p.x + side * p.nx * p.hw, y = p.y + side * p.ny * p.hw;
        box.x0 = Math.min(box.x0, x); box.x1 = Math.max(box.x1, x);
        box.y0 = Math.min(box.y0, y); box.y1 = Math.max(box.y1, y);
      }
    }
    return { pts: pts, box: box };
  }

  function bandAt(band, s) {
    const pts = band.pts; s = clamp(s, 0, 1);
    let i = 1;
    while (i < pts.length - 1 && pts[i].s < s) i++;
    const a = pts[i - 1], b = pts[i];
    const t = (s - a.s) / ((b.s - a.s) || 1);
    const tx = lerp(a.tx, b.tx, t), ty = lerp(a.ty, b.ty, t), l = Math.hypot(tx, ty) || 1;
    return { x: lerp(a.x, b.x, t), y: lerp(a.y, b.y, t), hw: lerp(a.hw, b.hw, t), tx: tx / l, ty: ty / l, nx: -ty / l, ny: tx / l, s: s };
  }

  /* Adds the band section [s0, s1] as consistently wound quads (a union that tolerates folds at tight turns). */
  function bandPath(ctx, band, s0, s1, widen) {
    widen = widen || 1;
    const pts = [bandAt(band, s0)];
    for (let i = 0; i < band.pts.length; i++) { const p = band.pts[i]; if (p.s > s0 && p.s < s1) pts.push(p); }
    pts.push(bandAt(band, s1));
    ctx.beginPath();
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i], b = pts[i + 1];
      const q = [
        [a.x - a.nx * a.hw * widen, a.y - a.ny * a.hw * widen], [b.x - b.nx * b.hw * widen, b.y - b.ny * b.hw * widen],
        [b.x + b.nx * b.hw * widen, b.y + b.ny * b.hw * widen], [a.x + a.nx * a.hw * widen, a.y + a.ny * a.hw * widen]
      ];
      let area = 0;
      for (let k = 0; k < 4; k++) { const u = q[k], v = q[(k + 1) % 4]; area += u[0] * v[1] - v[0] * u[1]; }
      if (area < 0) q.reverse();
      ctx.moveTo(q[0][0], q[0][1]); ctx.lineTo(q[1][0], q[1][1]); ctx.lineTo(q[2][0], q[2][1]); ctx.lineTo(q[3][0], q[3][1]);
      ctx.closePath();
    }
  }

  /* Edge polylines of the band section, for stitched outlines. */
  function bandEdges(band, s0, s1) {
    const L = [], Rr = [];
    const push = function (p) { L.push([p.x - p.nx * p.hw, p.y - p.ny * p.hw]); Rr.push([p.x + p.nx * p.hw, p.y + p.ny * p.hw]); };
    push(bandAt(band, s0));
    for (let i = 0; i < band.pts.length; i++) { const p = band.pts[i]; if (p.s > s0 && p.s < s1) push(p); }
    push(bandAt(band, s1));
    return [L, Rr];
  }

  function polyline(ctx, pts) {
    ctx.beginPath();
    for (let i = 0; i < pts.length; i++) { if (i) ctx.lineTo(pts[i][0], pts[i][1]); else ctx.moveTo(pts[i][0], pts[i][1]); }
  }

  function roundRect(ctx, x, y, w, h, r) {
    r = Math.min(r, h / 2, w / 2);
    ctx.beginPath();
    ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y); ctx.arcTo(x + w, y, x + w, y + r, r);
    ctx.lineTo(x + w, y + h - r); ctx.arcTo(x + w, y + h, x + w - r, y + h, r);
    ctx.lineTo(x + r, y + h); ctx.arcTo(x, y + h, x, y + h - r, r);
    ctx.lineTo(x, y + r); ctx.arcTo(x, y, x + r, y, r);
    ctx.closePath();
  }

  /* Small deterministic hash noise for cosmetic variation (no shared RNG state). */
  function hash(n) { const s = Math.sin(n * 127.1 + 311.7) * 43758.5453; return s - Math.floor(s); }

  WW.render.util = {
    clamp: clamp, lerp: lerp, smooth: smooth, easeOutCubic: easeOutCubic, easeInOut: easeInOut, easeOutBack: easeOutBack,
    makeCanvas: makeCanvas, canFilter: canFilter, imgReady: imgReady,
    drawFrame: drawFrame, frameCanvas: frameCanvas, silhouette: silhouette,
    glowSprite: glowSprite, shadowSprite: shadowSprite, drawShadow: drawShadow, star: star,
    polyPath: polyPath, polyBox: polyBox, boxHit: boxHit, polyline: polyline, roundRect: roundRect,
    buildBand: buildBand, bandAt: bandAt, bandPath: bandPath, bandEdges: bandEdges, hash: hash
  };
})(globalThis.WW = globalThis.WW || {});
/* Wishweave Wonders — renderer camera (WW.render.camera), docs/ARCHITECTURE.md §8 "Fit" and "Camera".

   fit       contain-fit of the 841 × 1870 plate into the CSS canvas: s0 CSS px per plate px, (x0, y0) plate origin.
   camera    {plate, z, fx, fy}: zoom over the fit and the plate point (fx, fy) shown at the canvas centre.
   view      {plate, s, ox, oy}: screen = (ox + x * s, oy + y * s) in CSS px; drawn with one setTransform.

   Target for Purl at path sample {x, y, w}: z = clamp(w0 / w, 1, zMax) (w0 = path start width) keeps him at a constant
   size; as z rises his screen anchor blends from where the contain-fit puts him toward (centre, anchorY · H); the view
   is then clamped inside the plate. At z = 1 the view is exactly the contain-fit, i.e. the approved composition. */
(function (WW) {
  'use strict';
  WW.render = WW.render || {};
  const U = function () { return WW.render.util; };
  const PW = 841, PH = 1870;

  function fit(W, H) {
    const s0 = Math.min(W / PW, H / PH);
    return { s0: s0, x0: (W - PW * s0) / 2, y0: (H - PH * s0) / 2, W: W, H: H };
  }

  function exitF(P) {
    const ev = (P.purl && P.purl.events) || [];
    for (let i = 0; i < ev.length; i++) if (ev[i].type === 'exit') return ev[i].f;
    return 1;
  }

  function eventF(P, type, fallback) {
    const ev = (P.purl && P.purl.events) || [];
    for (let i = 0; i < ev.length; i++) if (ev[i].type === type) return ev[i].f;
    return fallback;
  }

  /* Zoom baseline: the path width where the plate's approved composition is framed — the entry stop when the plate
     has one near its start (Purl waits there, so the view at the stop equals the contain-fit), else the path start. */
  const baseCache = new WeakMap();   // plate data is shared and never written to
  function baseWidth(P) {
    let w = baseCache.get(P);
    if (w) return w;
    const path = P.purl.path;
    const stop = eventF(P, 'stop', null);
    w = stop !== null && stop < 0.15 ? WW.path.sample(path, stop).w : path[0][2];
    baseCache.set(P, w);
    return w;
  }

  /* Camera target for Purl at path fraction f on plate P (lane-0 point; his lane offset shows on screen). */
  function target(fitInfo, P, f) {
    const u = U();
    const path = P.purl.path;
    const s = WW.path.sample(path, f);
    const w0 = baseWidth(P);
    const zMax = (P.camera && P.camera.zMax) || 1.8;
    const anchorY = (P.camera && P.camera.anchorY) || 0.8;
    const z = u.clamp(w0 / Math.max(1, s.w), 1, zMax);
    const b = zMax > 1 ? u.smooth((z - 1) / (zMax - 1)) : 0;
    const W = fitInfo.W, H = fitInfo.H, s0 = fitInfo.s0;
    const nx = fitInfo.x0 + s.x * s0, ny = fitInfo.y0 + s.y * s0;     // where the contain-fit shows him
    const ax = u.lerp(nx, W / 2, b), ay = u.lerp(ny, anchorY * H, b);
    const k = s0 * z;
    let fx = s.x - (ax - W / 2) / k, fy = s.y - (ay - H / 2) / k;
    return clampCam(fitInfo, { plate: P.id, z: z, fx: fx, fy: fy });
  }

  function clampCam(fitInfo, cam) {
    const k = fitInfo.s0 * cam.z;
    const hw = fitInfo.W / (2 * k), hh = fitInfo.H / (2 * k);
    cam.fx = 2 * hw >= PW ? PW / 2 : Math.min(Math.max(cam.fx, hw), PW - hw);
    cam.fy = 2 * hh >= PH ? PH / 2 : Math.min(Math.max(cam.fy, hh), PH - hh);
    return cam;
  }

  /* Frame-rate independent follow; ~0.2 s to settle. */
  function follow(cam, tgt, dt) {
    const d = WW.util.damp;
    cam.z = d(cam.z, tgt.z, 0.07, dt);
    cam.fx = d(cam.fx, tgt.fx, 0.07, dt);
    cam.fy = d(cam.fy, tgt.fy, 0.07, dt);
    return cam;
  }

  function view(fitInfo, cam, dx) {
    const s = fitInfo.s0 * cam.z;
    return { plate: cam.plate, s: s, ox: fitInfo.W / 2 - cam.fx * s + (dx || 0), oy: fitInfo.H / 2 - cam.fy * s, z: cam.z, cam: cam };
  }

  function toScreen(v, x, y) { return { x: v.ox + x * v.s, y: v.oy + y * v.s }; }

  WW.render.camera = { fit: fit, target: target, clampCam: clampCam, follow: follow, view: view, toScreen: toScreen,
    exitF: exitF, eventF: eventF, PW: PW, PH: PH };
})(globalThis.WW = globalThis.WW || {});

/* Wishweave Wonders — plate background layers (WW.render.world), docs/ARCHITECTURE.md §8 "Fit", "Layers",
   "Route openings" and occluders.

   framing      cached blurred, darkened copy of a plate, cover-fitted behind the contain-fit (never stretched)
   plate        the clean plate (only its visible source rectangle is sampled)
   route ghost  the clean plates show OPENED routes; before a ribbon/shortcut opens, the not-yet-woven part of its band
                (roll position → far end) is drawn as a pale, desaturated, shimmering ghost with stitched edges, and a carpet
                roll (coral-tinted on the ribbon) sits at the band start. While animating, the roll travels the band
                (half-widths offset along the band normal) revealing the full-colour plate behind it. Open = untouched plate.
   occluders    redraw this background inside a polygon over actors that are farther away (ground y < behindY). */
(function (WW) {
  'use strict';
  WW.render = WW.render || {};
  const U = function () { return WW.render.util; };
  const PW = 841, PH = 1870;

  /* Sub-rectangle of feat.carpet-rolled holding only the rolled cylinder (frame-relative). */
  const ROLL_SUB = { x: 92, y: 3, w: 333, h: 108 };

  function plateImg(R, plateId) {
    const P = R.plates[plateId];
    return R.images[(P && P.image) || plateId];
  }

  /* ---------- framing ---------- */
  function framingCanvas(R, plateId) {
    const key = 'framing:' + plateId;
    if (R.cache[key]) return R.cache[key];
    const img = plateImg(R, plateId), u = U();
    if (!u.imgReady(img)) return null;
    const w = 106, h = 236;
    const c = u.makeCanvas(w, h), g = c.getContext('2d');
    if (u.canFilter()) {
      // blur at an intermediate size so the edges stay soft without per-frame filters
      const m = u.makeCanvas(212, 472), mg = m.getContext('2d');
      mg.drawImage(img, 0, 0, 212, 472);
      g.filter = 'blur(4px) saturate(0.85)';
      g.drawImage(m, -8, -8, w + 16, h + 16);
      g.filter = 'none';
    } else {
      const m = u.makeCanvas(27, 59); m.getContext('2d').drawImage(img, 0, 0, 27, 59);
      g.imageSmoothingEnabled = true; g.drawImage(m, 0, 0, w, h);
    }
    g.fillStyle = 'rgba(28, 12, 6, 0.5)';
    g.fillRect(0, 0, w, h);
    R.cache[key] = c;
    return c;
  }

  /* Screen-space framing behind a view; drawn only where the plate does not cover the target rectangle. */
  function drawFraming(R, ctx, v, rect) {
    const x0 = v.ox, y0 = v.oy, x1 = v.ox + PW * v.s, y1 = v.oy + PH * v.s;
    if (x0 <= rect.x + 0.5 && y0 <= rect.y + 0.5 && x1 >= rect.x + rect.w - 0.5 && y1 >= rect.y + rect.h - 0.5) return;
    const c = framingCanvas(R, v.plate);
    if (!c) { ctx.fillStyle = '#2b150c'; ctx.fillRect(rect.x, rect.y, rect.w, rect.h); return; }
    const W = R.fit.W, H = R.fit.H;
    const k = Math.max(W / PW, H / PH) * 1.04;
    const w = PW * k, h = PH * k;
    ctx.drawImage(c, (W - w) / 2, (H - h) / 2, w, h);
  }

  /* ---------- plate ---------- */
  function drawPlate(R, ctx, v, box) {
    const img = plateImg(R, v.plate);
    if (!U().imgReady(img)) return;
    const iw = img.naturalWidth || img.width, ih = img.naturalHeight || img.height;
    const kx = iw / PW, ky = ih / PH;
    // visible plate rectangle (optionally limited to a box), in plate px
    let x0 = Math.max(0, -v.ox / v.s), y0 = Math.max(0, -v.oy / v.s);
    let x1 = Math.min(PW, (R.fit.W - v.ox) / v.s), y1 = Math.min(PH, (R.fit.H - v.oy) / v.s);
    if (box) { x0 = Math.max(x0, box.x0 - 2); y0 = Math.max(y0, box.y0 - 2); x1 = Math.min(x1, box.x1 + 2); y1 = Math.min(y1, box.y1 + 2); }
    x0 = Math.floor(x0); y0 = Math.floor(y0); x1 = Math.ceil(x1); y1 = Math.ceil(y1);
    if (x1 <= x0 || y1 <= y0) return;
    ctx.drawImage(img, x0 * kx, y0 * ky, (x1 - x0) * kx, (y1 - y0) * ky, x0, y0, x1 - x0, y1 - y0);
  }

  /* ---------- route ghost + roll ---------- */
  function routeInfo(R, plateId) {
    const key = 'route:' + plateId;
    if (R.cache[key] !== undefined) return R.cache[key];
    const P = R.plates[plateId];
    let info = null;
    if (P && P.ribbon && P.ribbon.band) info = { kind: 'ribbon', stitch: 'ribbon', band: U().buildBand(P.ribbon.band) };
    else if (P && P.shortcut && P.shortcut.band) info = { kind: 'shortcut', stitch: 'shortcut', band: U().buildBand(P.shortcut.band) };
    if (info) {
      const b = info.band.box;
      info.box = { x0: Math.max(0, Math.floor(b.x0 - 6)), y0: Math.max(0, Math.floor(b.y0 - 6)),
        x1: Math.min(PW, Math.ceil(b.x1 + 6)), y1: Math.min(PH, Math.ceil(b.y1 + 6)) };
    }
    R.cache[key] = info;
    return info;
  }

  function ghostCanvas(R, plateId, info) {
    if (info.ghost) return info.ghost;
    const img = plateImg(R, plateId), u = U();
    if (!u.imgReady(img)) return null;
